-- Qala Saku schema, consolidated.
--
-- Qala Saku shares a Supabase project (and its auth.users, including Google
-- sign-in) with other apps, so everything lives in its own schema "saku"
-- instead of "public". This file is the final state of the earlier
-- migrations (now in supabase/migrations-legacy, which targeted "public" in
-- the previous project), generated by replaying them into "saku".
--
-- After applying: add "saku" to Dashboard > Project Settings > Data API >
-- Exposed schemas, otherwise the API returns 406 for every query.

-- Function bodies reference tables created further down.
set check_function_bodies = false;

CREATE SCHEMA saku;

CREATE FUNCTION saku.adjust_account_balance_on_opening_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'saku'
    AS $$
begin
  if (NEW.opening_balance <> OLD.opening_balance) then
    NEW.current_balance := NEW.current_balance - OLD.opening_balance + NEW.opening_balance;
  end if;
  return NEW;
end;
$$;

CREATE TABLE saku.savings_goals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    name text NOT NULL,
    target_amount numeric NOT NULL,
    saved_amount numeric DEFAULT 0 NOT NULL,
    target_date date,
    icon text,
    color text,
    archived boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT savings_goals_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 80))),
    CONSTRAINT savings_goals_saved_amount_check CHECK ((saved_amount >= (0)::numeric)),
    CONSTRAINT savings_goals_target_amount_check CHECK ((target_amount > (0)::numeric))
);

CREATE FUNCTION saku.contribute_savings_goal(goal_id uuid, delta numeric) RETURNS SETOF saku.savings_goals
    LANGUAGE sql
    SET search_path TO 'saku'
    AS $$
  update savings_goals
     set saved_amount = greatest(saved_amount + delta, 0)
   where id = goal_id and user_id = auth.uid()
  returning *;
$$;

CREATE FUNCTION saku.get_total_balance(account_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'saku'
    AS $_$
  select coalesce(sum(a.current_balance), 0)
  from accounts a
  where a.user_id = auth.uid()
    and (($1 is null and a.archived = false) or a.id = $1);
$_$;

CREATE FUNCTION saku.protect_profile_privileged_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'saku'
    AS $$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.plan := 'FREE';
      new.ai_unlimited := false;
      new.live_price_used_at := null;
    else
      new.plan := old.plan;
      new.ai_unlimited := old.ai_unlimited;
      new.live_price_used_at := old.live_price_used_at;
    end if;
  end if;
  return new;
end;
$$;

CREATE FUNCTION saku.report_budget_vs_actual(month_in text, type_in text DEFAULT 'expense'::text) RETURNS TABLE(category_id uuid, category_name text, planned numeric, actual numeric, diff numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'saku'
    AS $$
with me as (
  select auth.uid() as uid
),
planned as (
  select bi.category_id,
         sum(bi.amount)::numeric as planned
  from budgets b
  join me on me.uid = b.user_id
  join budget_items bi on bi.budget_id = b.id
  join categories c on c.id = bi.category_id
  where b.month = month_in
    and c.type::text = type_in
  group by bi.category_id
),
actual as (
  select t.category_id,
         sum(t.amount)::numeric as actual
  from transactions t
  join me on me.uid = t.user_id
  join categories c on c.id = t.category_id
  where t.type::text = type_in
    and t.category_id is not null
    and t.budget_month = month_in
  group by t.category_id
)
select
  coalesce(p.category_id, a.category_id) as category_id,
  (select c.name from categories c where c.id = coalesce(p.category_id, a.category_id)) as category_name,
  coalesce(p.planned, 0)::numeric as planned,
  coalesce(a.actual, 0)::numeric as actual,
  (coalesce(p.planned, 0) - coalesce(a.actual, 0))::numeric as diff
from planned p
full outer join actual a on a.category_id = p.category_id
order by 2 asc;
$$;

CREATE FUNCTION saku.set_account_initial_balance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'saku'
    AS $$
begin
  new.current_balance := new.opening_balance;
  return new;
end;
$$;

CREATE FUNCTION saku.update_account_current_balance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'saku'
    AS $$
begin
  if (TG_OP = 'INSERT') then
    if (NEW.type = 'income') then
      update accounts set current_balance = current_balance + NEW.amount where id = NEW.account_id;
    elsif (NEW.type = 'expense') then
      update accounts set current_balance = current_balance - NEW.amount where id = NEW.account_id;
    elsif (NEW.type = 'transfer') then
      update accounts set current_balance = current_balance - NEW.amount where id = NEW.from_account_id;
      update accounts set current_balance = current_balance + NEW.amount where id = NEW.to_account_id;
    end if;
    return NEW;
  elsif (TG_OP = 'UPDATE') then
    -- revert old values
    if (OLD.type = 'income') then
      update accounts set current_balance = current_balance - OLD.amount where id = OLD.account_id;
    elsif (OLD.type = 'expense') then
      update accounts set current_balance = current_balance + OLD.amount where id = OLD.account_id;
    elsif (OLD.type = 'transfer') then
      update accounts set current_balance = current_balance + OLD.amount where id = OLD.from_account_id;
      update accounts set current_balance = current_balance - OLD.amount where id = OLD.to_account_id;
    end if;
    -- apply new values
    if (NEW.type = 'income') then
      update accounts set current_balance = current_balance + NEW.amount where id = NEW.account_id;
    elsif (NEW.type = 'expense') then
      update accounts set current_balance = current_balance - NEW.amount where id = NEW.account_id;
    elsif (NEW.type = 'transfer') then
      update accounts set current_balance = current_balance - NEW.amount where id = NEW.from_account_id;
      update accounts set current_balance = current_balance + NEW.amount where id = NEW.to_account_id;
    end if;
    return NEW;
  elsif (TG_OP = 'DELETE') then
    if (OLD.type = 'income') then
      update accounts set current_balance = current_balance - OLD.amount where id = OLD.account_id;
    elsif (OLD.type = 'expense') then
      update accounts set current_balance = current_balance + OLD.amount where id = OLD.account_id;
    elsif (OLD.type = 'transfer') then
      update accounts set current_balance = current_balance + OLD.amount where id = OLD.from_account_id;
      update accounts set current_balance = current_balance - OLD.amount where id = OLD.to_account_id;
    end if;
    return OLD;
  end if;
  return NEW;
end;
$$;

CREATE FUNCTION saku.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'saku'
    AS $$
begin
  new.updated_at = timezone('utc', now());
  return new;
end;
$$;

CREATE TABLE saku.accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    name text NOT NULL,
    type text NOT NULL,
    currency text DEFAULT 'IDR'::text NOT NULL,
    opening_balance numeric DEFAULT 0 NOT NULL,
    archived boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    account_number text,
    current_balance numeric DEFAULT 0 NOT NULL,
    CONSTRAINT accounts_type_check CHECK ((type = ANY (ARRAY['bank'::text, 'ewallet'::text, 'cash'::text])))
);

CREATE TABLE saku.ai_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    feature text NOT NULL,
    created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE saku.budget_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    budget_id uuid NOT NULL,
    category_id uuid NOT NULL,
    amount numeric NOT NULL,
    rollover boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE saku.budgets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    month text NOT NULL,
    total_amount numeric DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE saku.categories (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    name text NOT NULL,
    type text NOT NULL,
    color text,
    icon text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT categories_type_check CHECK ((type = ANY (ARRAY['expense'::text, 'income'::text])))
);

CREATE TABLE saku.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    order_id text NOT NULL,
    product_name text NOT NULL,
    amount integer NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    token text NOT NULL,
    created_at timestamp with time zone DEFAULT now()
);

CREATE TABLE saku.profiles (
    id uuid NOT NULL,
    email text NOT NULL,
    name text NOT NULL,
    default_currency text DEFAULT 'IDR'::text NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    plan text DEFAULT 'FREE'::text NOT NULL,
    live_price_used_at timestamp with time zone,
    onboarding_completed boolean DEFAULT false NOT NULL,
    ai_unlimited boolean DEFAULT false NOT NULL,
    CONSTRAINT profiles_plan_check CHECK ((plan = ANY (ARRAY['FREE'::text, 'PRO'::text])))
);

CREATE TABLE saku.recurring_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    type text NOT NULL,
    account_id uuid,
    from_account_id uuid,
    to_account_id uuid,
    category_id uuid,
    amount numeric NOT NULL,
    note text DEFAULT ''::text NOT NULL,
    frequency text NOT NULL,
    day_of_month smallint,
    start_date date NOT NULL,
    next_date date NOT NULL,
    end_date date,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT recurring_transactions_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT recurring_transactions_check CHECK ((((type = 'transfer'::text) AND (from_account_id IS NOT NULL) AND (to_account_id IS NOT NULL) AND (from_account_id <> to_account_id) AND (account_id IS NULL) AND (category_id IS NULL)) OR ((type <> 'transfer'::text) AND (account_id IS NOT NULL) AND (from_account_id IS NULL) AND (to_account_id IS NULL)))),
    CONSTRAINT recurring_transactions_check1 CHECK (((frequency = 'weekly'::text) OR (day_of_month IS NOT NULL))),
    CONSTRAINT recurring_transactions_day_of_month_check CHECK (((day_of_month >= 1) AND (day_of_month <= 31))),
    CONSTRAINT recurring_transactions_frequency_check CHECK ((frequency = ANY (ARRAY['weekly'::text, 'monthly'::text]))),
    CONSTRAINT recurring_transactions_type_check CHECK ((type = ANY (ARRAY['expense'::text, 'income'::text, 'transfer'::text])))
);

CREATE TABLE saku.transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    date date NOT NULL,
    type text NOT NULL,
    account_id uuid,
    from_account_id uuid,
    to_account_id uuid,
    amount numeric NOT NULL,
    category_id uuid,
    note text,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    budget_month text DEFAULT to_char(timezone('utc'::text, now()), 'YYYY-MM'::text) NOT NULL,
    actual_date date DEFAULT (timezone('utc'::text, now()))::date NOT NULL,
    recurring_id uuid,
    CONSTRAINT transactions_type_check CHECK ((type = ANY (ARRAY['expense'::text, 'income'::text, 'transfer'::text])))
);

