CREATE TRIGGER accounts_adjust_balance_before_update BEFORE UPDATE ON saku.accounts FOR EACH ROW EXECUTE FUNCTION saku.adjust_account_balance_on_opening_update();

CREATE TRIGGER accounts_set_initial_balance BEFORE INSERT ON saku.accounts FOR EACH ROW EXECUTE FUNCTION saku.set_account_initial_balance();

CREATE TRIGGER profiles_protect_privileged_columns BEFORE INSERT OR UPDATE ON saku.profiles FOR EACH ROW EXECUTE FUNCTION saku.protect_profile_privileged_columns();

CREATE TRIGGER transactions_update_account_balance AFTER INSERT OR DELETE OR UPDATE ON saku.transactions FOR EACH ROW EXECUTE FUNCTION saku.update_account_current_balance();

CREATE TRIGGER update_accounts_updated_at BEFORE UPDATE ON saku.accounts FOR EACH ROW EXECUTE FUNCTION saku.update_updated_at_column();

CREATE TRIGGER update_budget_items_updated_at BEFORE UPDATE ON saku.budget_items FOR EACH ROW EXECUTE FUNCTION saku.update_updated_at_column();

CREATE TRIGGER update_budgets_updated_at BEFORE UPDATE ON saku.budgets FOR EACH ROW EXECUTE FUNCTION saku.update_updated_at_column();

CREATE TRIGGER update_categories_updated_at BEFORE UPDATE ON saku.categories FOR EACH ROW EXECUTE FUNCTION saku.update_updated_at_column();

CREATE TRIGGER update_profiles_updated_at BEFORE UPDATE ON saku.profiles FOR EACH ROW EXECUTE FUNCTION saku.update_updated_at_column();

CREATE TRIGGER update_recurring_transactions_updated_at BEFORE UPDATE ON saku.recurring_transactions FOR EACH ROW EXECUTE FUNCTION saku.update_updated_at_column();

CREATE TRIGGER update_savings_goals_updated_at BEFORE UPDATE ON saku.savings_goals FOR EACH ROW EXECUTE FUNCTION saku.update_updated_at_column();

CREATE TRIGGER update_transactions_updated_at BEFORE UPDATE ON saku.transactions FOR EACH ROW EXECUTE FUNCTION saku.update_updated_at_column();

