CREATE POLICY "AI logs are insertable by owner" ON saku.ai_logs FOR INSERT WITH CHECK (((auth.jwt() ->> 'email'::text) = email));

CREATE POLICY "AI logs are readable by owner" ON saku.ai_logs FOR SELECT USING (((auth.jwt() ->> 'email'::text) = email));

CREATE POLICY "Accounts are accessible by owner" ON saku.accounts USING ((user_id = auth.uid())) WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "Budget items are accessible by owner" ON saku.budget_items USING ((EXISTS ( SELECT 1
   FROM saku.budgets b
  WHERE ((b.id = budget_items.budget_id) AND (b.user_id = auth.uid()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM saku.budgets b
  WHERE ((b.id = budget_items.budget_id) AND (b.user_id = auth.uid())))));

CREATE POLICY "Budgets are accessible by owner" ON saku.budgets USING ((user_id = auth.uid())) WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "Categories are accessible by owner" ON saku.categories USING ((user_id = auth.uid())) WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "Payments are readable by owner" ON saku.payments FOR SELECT USING ((user_id = auth.uid()));

CREATE POLICY "Profiles are accessible by owner" ON saku.profiles USING ((id = auth.uid())) WITH CHECK ((id = auth.uid()));

CREATE POLICY "Recurring transactions are accessible by owner" ON saku.recurring_transactions USING ((user_id = auth.uid())) WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "Savings goals are accessible by owner" ON saku.savings_goals USING ((user_id = auth.uid())) WITH CHECK ((user_id = auth.uid()));

CREATE POLICY "Transactions are accessible by owner" ON saku.transactions USING ((user_id = auth.uid())) WITH CHECK ((user_id = auth.uid()));

