-- API access. RLS policies above still decide which rows each user sees.
grant usage on schema saku to anon, authenticated, service_role;
grant select, insert, update, delete on all tables in schema saku to authenticated;
grant all on all tables in schema saku to service_role;
revoke execute on all functions in schema saku from public;
grant execute on all functions in schema saku to authenticated, service_role;
alter default privileges in schema saku grant select, insert, update, delete on tables to authenticated;
alter default privileges in schema saku grant all on tables to service_role;
alter default privileges in schema saku revoke execute on functions from public;
alter default privileges in schema saku grant execute on functions to authenticated, service_role;
